import numpy as np
from sim import Sim

def rollout(ctrl_mode='zero',steps=1500):
    sim=Sim(); home=sim.home_ctrl()
    for _ in range(steps):
        if ctrl_mode=='zero':
            sim.data.ctrl[:] = 0
        elif ctrl_mode=='home_as_tau':
            sim.data.ctrl[:] = home
        sim.step(1)
        p=sim.pelvis_position();
        if p[2] < 0.15:
            break
    print(ctrl_mode,'steps',len(sim._ctrl_trace),'pelvis',sim.pelvis_position(),'torso',sim.torso_up())

for mode in ['zero','home_as_tau']:
    rollout(mode)
